def is_triangle_free(edges, n):
    adj = [[False]*n for _ in range(n)]
    for u,v in edges:
        adj[u][v] = adj[v][u] = True
    for u in range(n):
        for v in range(u+1, n):
            if adj[u][v]:
                for w in range(v+1, n):
                    if adj[u][w] and adj[v][w]:
                        return False
    return True

def is_maximal(edges, n):
    if not is_triangle_free(edges, n):
        return False
    # Try adding any missing edge
    adj = [[False]*n for _ in range(n)]
    for u,v in edges:
        adj[u][v] = adj[v][u] = True
    for u in range(n):
        for v in range(u+1, n):
            if not adj[u][v]:
                # Check if adding (u,v) creates a triangle
                creates_triangle = False
                for w in range(n):
                    if w != u and w != v and adj[u][w] and adj[v][w]:
                        creates_triangle = True
                        break
                if not creates_triangle:
                    return False  # Can add edge without creating triangle
    return True

